import{_ as a,H as r,f as e,i as t}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第四章 放浪の旅","description":"","frontmatter":{},"headers":[],"relativePath":"story/1-2.md","filePath":"story/1-2.md"}'),o={name:"story/1-2.md"};function h(s,p,n,i,_,l){return r(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="第四章-放浪の旅" tabindex="-1">第四章 放浪の旅 <a class="header-anchor" href="#第四章-放浪の旅" aria-label="Permalink to &quot;第四章 放浪の旅&quot;">​</a></h1><p>旅に目的地はなかった。</p><p>目的地があれば、それは旅ではなく遠征だ。三匹が選んだのは、あてのない旅だった。</p><p>正確には。</p><p>「もう二度と、あんな悲劇を起こしたくない。」</p><p>という、形のない誓いだけを持った旅だった。</p><p>真紅の森を抜ける。</p><p>歪んだ森の紫色の霧の中を進む。</p><p>足元が黒い火山岩に変わる頃、玄武岩デルタに入っていた。</p><p>ネザーは広い。オーレックスが本で読んでいた以上に、広かった。そしてその広さの分だけ、悲劇も多かった。</p><hr><p>最初の村に着いたのは、旅に出て三日目のことだった。</p><p>村の入口に立った時、異変はすぐに分かった。</p><p>静かすぎた。</p><p>市場があるはずの広場が、がらんとしていた。老人が一人、家の前にうずくまっていた。</p><p>「どうしたんですか。」</p><p>オーレックスが声をかける。老人は顔を上げた。目の下に深い影があった。</p><p>「盗賊団が……食料を全部持っていった……。」</p><p>「今朝も来た。明日も来る。毎日来る。」</p><p>声に感情がなかった。諦めの色が、全身を覆っていた。</p><p>「場所を教えてください。」</p><p>老人は震える手で方角を指した。</p><p>「俺に任せろ。」</p><p>スターリンが大斧を担ぎ直した。溶岩の光を受けて、刃が鈍く光る。</p><p>「お前一人で行くのか？」</p><p>「二人は見ててもいい。でも見てな。俺が盗賊ってどんな奴かって話してやるから。」</p><p>そして、スターリンは一人で歩いていった。</p><hr><p>数十分後。</p><p>荒野の向こうから、叫び声が聞こえた。</p><p>「ひぃぃぃ！！」</p><p>「化け物だ！！」</p><p>そして。</p><p>盗賊団十五人が、一目散に逃げてきた。その後ろを、スターリンが悠々と歩いていた。大斧は肩に担いだまま。一度も振っていない。</p><p>「おい逃げんな！！格好つかねえだろ！！」</p><p>背中に向かって叫ぶ。盗賊たちは振り返りもせずに消えていった。</p><p>「……何したんだ。」</p><p>「大斧見せながら笑いかけてやった。ただそれだけ。」</p><p>「圧倒的な笑顔の前には全員逃げる。」</p><p>「それ、理論じゃなくて経験談だよね。」</p><p>ピックバーグが呆れた声で言った。</p><p>しかし、食料は戻ってきた。村人たちが倉庫の扉を開けると、中身はまだあった。子供たちが駆け寄ってくる。老人は膝をついて泣いた。</p><p>「ありがとう……。ありがとう……。」</p><p>その日の夜、三匹は村の外で焚き火を囲んだ。</p><p>「悪くないな。」</p><p>スターリンが言った。</p><p>「何が。」</p><p>「助けるのが。俺、ずっと斧使って戦うのが目的みたいな生き方してたけど。なんか今日の方がしっくりきた。」</p><p>「お前が言うと意外だな。」</p><p>「俺だって成長する。」</p><p>ピックバーグがノートに何かを書き込みながら言った。</p><p>「ということは、今日のことをまとめると。スターリンの戦略は、威圧による心理的降伏の誘導。」</p><p>「うるせえ難しい言葉で言うな。」</p><p>「笑って脅した、ってこと。」</p><p>「そうだよ！！」</p><p>オーレックスは二人の声を聞きながら、暗いネザーの空を見上げた。</p><p>父が言っていた。「いつか、お前にも分かるさ。」</p><p>少しだけ、分かった気がした。</p><hr><p>次の村では、川を渡れなかった。</p><p>橋が崩れていたのだ。</p><p>主要な交易路の橋が落ちれば、村は孤立する。食料も、薬も、情報も。何も届かなくなる。</p><p>「どのくらい前に落ちたんですか。」</p><p>「四ヶ月前に。」</p><p>「四ヶ月……。」</p><p>ピックバーグは川の両岸を眺めた。川幅。流れの速さ。岸の地盤。全てを観察する目で見た。</p><p>「僕に考えがある。」</p><p>鞄からノートを取り出す。鉛筆が走る。</p><p>「ここをこうして……支柱はここ……荷重の分散を考えると……。」</p><p>「読めない。」</p><p>スターリンが覗き込む。</p><p>「字じゃなくて図面だから。」</p><p>「天才って字が汚いな。」</p><p>「君は黙って岩を運ぶ担当でいいよ。」</p><hr><p>三日かかった。</p><p>スターリンが岩を運び、オーレックスが木を切り、ピックバーグが計算して指示を出した。</p><p>四日目の朝。</p><p>橋は完成した。</p><p>村人たちが渡ってみる。</p><p>揺れない。壊れない。</p><p>「ありがとう！！」</p><p>「これで市場に行ける！！」</p><p>涙を流す者もいた。</p><p>「僕はちゃんと計算が合うか確認したかっただけなんだけど。」</p><p>ピックバーグが小声でオーレックスに言った。</p><p>「ありがとうって言われるのは悪くないよね。」</p><p>「……まあ、うん。」</p><p>ピックバーグは少し赤くなった。眼鏡の奥で。</p><hr><p>旅の中で、オーレックスは一つのことを繰り返し考えた。</p><p>「争うことより、誰かを助ける方がずっといい。」</p><p>それは当たり前のことのようで、しかしこの世界では当たり前ではなかった。だから繰り返し思った。当たり前にしたかったから。</p><p>少しずつ、三匹の噂が広まっていった。</p><hr><h1 id="第五章-黄金の噂" tabindex="-1">第五章 黄金の噂 <a class="header-anchor" href="#第五章-黄金の噂" aria-label="Permalink to &quot;第五章 黄金の噂&quot;">​</a></h1><p>噂は、風に乗る。</p><p>「聞いたか。」</p><p>「ああ、あの話か。」</p><p>「大斧を持った大男と、変な眼鏡の学者と……。」</p><p>「金色の目をした若者だ。」</p><p>「三匹の旅人。助けてくれるらしい。」</p><p>「本当に？」</p><p>「本当に。うちの村がそうだった。」</p><p>噂の種は、三匹が通った村から村へと撒かれていった。水が低い方へ流れるように、自然と広がっていった。</p><p>「黄金の旅人」</p><p>「真紅の森の救世主」</p><p>「三匹の英雄」</p><p>呼び名は様々だったが、どれも同じ存在を指していた。</p><p>そしてその呼び名は、気が付けばオーレックスたちの元にも届くようになった。</p><p>ある村の子供が走ってきて、オーレックスに言った。</p><p>「あなたが黄金の旅人ですか！？英雄ですか！？」</p><p>目をキラキラさせながら。</p><p>「え、いや。」</p><p>「そうだよ！英雄だよ！」</p><p>スターリンが代わりに答えた。</p><p>「この子が英雄で、俺は最強の大斧使いで、そっちが天才研究家だ！」</p><p>「やめろ、恥ずかしい。」</p><p>「なんで恥ずかしいんだ、事実だろ！」</p><p>「大げさだよ、本当に。」</p><p>オーレックスは苦笑した。「僕たちは特別じゃない。ただ、目の前にある困りごとを解決しているだけだ。」</p><p>するとピックバーグが言った。</p><p>「でも、それを続けてきたのは事実だよ。」</p><p>「特別じゃないことを、毎日続けること。それが、特別なんだと思う。」</p><p>オーレックスはしばらく、その言葉を黙って考えた。</p><p>ネザーに風はないのに、何かが頬を撫でた気がした。</p><hr><h1 id="第六章-忘れられた砦" tabindex="-1">第六章 忘れられた砦 <a class="header-anchor" href="#第六章-忘れられた砦" aria-label="Permalink to &quot;第六章 忘れられた砦&quot;">​</a></h1><p>旅に出て八年目。</p><p>二十三歳になったオーレックスたちは、ある地図を手に入れた。</p><p>正確には「地図のようなもの」だった。古代文字で書かれた羊皮紙。ピックバーグが解読した。</p><p>「忘れられた砦の場所だ。」</p><p>「忘れられた砦？」</p><p>「伝説がある。数百年前に栄えた古代王国の、最後の城塞。誰も近づかないとされている。」</p><p>「なぜ。」</p><p>「罠が多いから。」</p><p>「……お前は喜んでるな。」</p><p>「当然。罠は文化の結晶だよ。」</p><p>「文化の結晶で俺が死にかけるのは何度目になるんだ。」</p><p>「十七回かな。」</p><p>「数えてたのか。」</p><p>こうして三匹は、「忘れられた砦」を目指した。</p><hr><p>砦は、あった。</p><p>あった、というより、そこに「存在していた」という方が正確だった。</p><p>玄武岩の大地に、突然現れた巨大な構造物。外壁は数百年の風化を経てなお厚く、それが逆に無数の年月の重みを感じさせた。入口のアーチには、見たことのない文字が刻まれていた。</p><p>「……なんて書いてある？」</p><p>「解読中。」</p><p>「この雰囲気、なんか好きだな。」</p><p>スターリンが言った。「こういう廃墟、なんかワクワクする。」</p><p>「入っても大丈夫か？」</p><p>「多分。」</p><p>「多分？」</p><p>「確率的に。」</p><p>「曖昧すぎる。」</p><p>スターリンは迷わず中へ入った。</p><p>「待って！罠の確認が終わってない！」</p><p>ピックバーグが叫ぶ。</p><p>カチッ。</p><p>「え？」</p><p>石の床の一部が沈む感触。</p><p>「スターリン！！」</p><p>ガラガラガラガラ！！</p><p>床が崩れた。</p><p>「ぎゃああああああ！！」</p><p>重力に引かれて、スターリンが消えた。</p><p>静寂。</p><p>「……また。」</p><p>ピックバーグは眼鏡の奥で目を閉じた。</p><p>「また！！」</p><p>穴の下から、スターリンの声が響いた。</p><p>「生きてたか。」</p><p>「今度は何メートル落ちた？」</p><p>「五メートルくらい！！床、柔らかかった！！」</p><p>「それは不幸中の幸いだね。」</p><p>「待ってろ、縄を投げる。」</p><p>こうして、何十もの罠をくぐり抜け、三匹は砦の最深部へ進んだ。罠に引っかかるたびにスターリンが叫び、ピックバーグが呆れ、オーレックスが助けた。それでも三匹は前に進んだ。</p><hr><p>最深部は、静かだった。</p><p>外の通路の複雑な罠が嘘のように、広い空間が広がっていた。</p><p>天井は高く、どこかから光が差し込んでいた。溶岩の光ではない。何か別の、金色がかった光だった。</p><p>部屋の中央に、</p><p>巨大な祭壇があった。</p><p>黒光りする石材で作られた、荘厳な台座。</p><p>そして。</p><p>その中央に。</p><p>一つの冠が、静かに置かれていた。</p><p>黄金の冠。</p><p>誰も近づいていないはずなのに、埃一つ積もっていなかった。まるで、今日置かれたばかりのように。</p><p>「……。」</p><p>誰も声を出せなかった。三匹は、しばらくそこに立ち尽くしていた。ただ見ていた。</p><p>「なんだ……あれ。」</p><p>スターリンが、珍しく小声で言った。</p><p>ピックバーグは祭壇の周囲の壁へ歩いていった。古代文字が刻まれている。指でなぞる。読む。</p><p>「まさか……。」</p><p>声が震えた。</p><p>「どういうこと？」</p><p>オーレックスが尋ねる。</p><p>ピックバーグは振り返った。眼鏡の奥の目が、いつもとは違う光を帯びていた。</p><p>「古文書によれば。」</p><p>声を整えながら、ゆっくりと読み上げる。</p><p>『真に民を想う者現れし時。』</p><p>『黄金の冠は再び輝く。』</p><p>『その者は争いを終わらせ、王国を築くだろう。』</p><p>「……。」</p><p>静寂が、部屋を満たした。</p><p>「王様の冠ってことか？」</p><p>スターリンが言った。「伝説のものが、本当にあったわけだ。」</p><p>「そんな馬鹿な。」</p><p>オーレックスは笑おうとした。しかし、笑えなかった。</p><p>「僕が王様？ありえないよ。この旅は、誰かを支配したくてしてきたんじゃない。ただ、みんなに普通に生きてほしくて。だから旅してきたんだ。」</p><p>しかし。</p><p>足が、動いた。</p><p>意思とは別に、まるで冠の方から引き寄せられるように。</p><p>一歩。</p><p>また一歩。</p><p>「オーレックス？」</p><p>スターリンの声が、遠く聞こえた。</p><p>祭壇の前に立った。冠を見る。近くで見ると、細かい装飾が施されていた。刻まれた模様が、旅で見てきた無数の村の紋章に似ていた。</p><p>「……。」</p><p>右手を伸ばした。</p><p>そっと。</p><p>指先が、冠の縁に触れた。</p><p>その瞬間。</p><p>ゴオオオオオオオ！！！</p><p>世界が変わった。</p><p>光だった。冠から、床から、壁から、天井から。全てが黄金色の光を放ち始めた。</p><p>「なっ！？」</p><p>「うおおおおお！？」</p><p>スターリンが飛び上がる。</p><p>「遺跡全体が反応してる！！これは……！！」</p><p>ピックバーグの声が、光の中で揺れた。</p><p>光の中で、オーレックスは一人だった。</p><p>否、一人ではなかった。</p><p>声があった。目に見えない何かが、真っ直ぐに語りかけてくる。</p><p>『力によって支配するな。』</p><p>『知恵によって導け。』</p><p>『民を守る者こそ、王となる。』</p><p>そして。</p><p>『黄金とは、富ではない。』</p><p>『希望そのものである。』</p><p>声が消えた。光が消えた。ゆっくりと、部屋は元の薄暗さに戻った。</p><p>冠は、オーレックスの手の中にあった。</p><p>静寂。</p><p>「……お前。光ってたぞ。」</p><p>スターリンが呟いた。「体全体が。光の柱みたいに。」</p><p>ピックバーグは祭壇の文字を読み返しながら言った。</p><p>「間違いない。これが、伝説の冠だ。そして……。」</p><p>二人はオーレックスを見た。</p><p>オーレックスは冠を見つめていた。手の中の冠を。</p><p>軽かった。素材が金なのに、不思議なほど軽かった。</p><p>「お前……王になる者なんじゃないか？」</p><p>「いや、君は……。」</p><p>オーレックスは静かに首を振った。</p><p>「違う。」</p><p>「僕は王になりたいわけじゃない。」</p><p>「ただ。」</p><p>「もう誰にも悲しい思いをしてほしくない。」</p><p>「それだけだ。」</p><p>その言葉を聞き、ピックバーグは静かに微笑んだ。</p><p>「だからこそ。」</p><p>「君は王になれるんだ。」</p><p>スターリンは何も言わなかった。ただ腕を組んで、天井を仰いだ。</p><p>目の端が、少し赤かった。</p><p>運命という言葉は好きではなかった。</p><p>しかし。</p><p>確かに、何かが動いた。この瞬間、確かに何かが動いた。</p><p>こうして。</p><p>歯車は静かに、回り始めた。</p>',269)])])}const f=a(o,[["render",h]]);export{c as __pageData,f as default};
